create table if not exists public.parking_calendar_dates(unit_id uuid not null references public.parking_units(id) on delete cascade,calendar_date date not null,label text not null check (char_length(btrim(label)) between 2 and 120),is_holiday boolean not null default true,created_at timestamptz not null default now(),created_by uuid references auth.users(id),primary key(unit_id,calendar_date)); alter table public.parking_calendar_dates enable row level security; drop policy if exists parking_calendar_read_staff on public.parking_calendar_dates; create policy parking_calendar_read_staff on public.parking_calendar_dates for select to authenticated using (private.has_unit_role(unit_id,array['owner','manager','operator','finance','auditor']::public.app_role[])); revoke all on public.parking_calendar_dates from public,anon; revoke insert,update,delete,truncate,references,trigger on public.parking_calendar_dates from authenticated; grant select on public.parking_calendar_dates to authenticated; grant all on public.parking_calendar_dates to service_role;
create or replace function public.upsert_parking_calendar_date(target_unit uuid,target_date date,target_label text,target_is_holiday boolean) returns date language plpgsql security definer set search_path=pg_catalog,public,private,auth as $$ declare actor uuid; begin actor:=private.monthly_assert_admin(target_unit); if target_date is null or char_length(btrim(target_label))<2 then raise exception 'INVALID_CALENDAR_DATE' using errcode='22023'; end if; insert into public.parking_calendar_dates(unit_id,calendar_date,label,is_holiday,created_by) values(target_unit,target_date,btrim(target_label),target_is_holiday,actor) on conflict(unit_id,calendar_date) do update set label=excluded.label,is_holiday=excluded.is_holiday; insert into public.audit_logs(actor_user_id,unit_id,action,metadata) values(actor,target_unit,'capacity.calendar.upserted',jsonb_build_object('date',target_date,'label',target_label,'holiday',target_is_holiday)); return target_date; end $$; revoke all on function public.upsert_parking_calendar_date(uuid,date,text,boolean) from public,anon; grant execute on function public.upsert_parking_calendar_date(uuid,date,text,boolean) to authenticated;;
